import {esc} from './ui.js';
import {getPreferences} from './preferences.js';
const cache=new Map(),requests=new Set(),widgets=new WeakMap();let started=false,generation=0;
export function translationHTML(point){if(!point?.authorId)return '';const target=getPreferences().language==='zh-CN'?'en':getPreferences().language;return `<section class="community-translation" data-translation-point="${esc(point.id)}" data-translation-version="${esc(point.version||point.description)}"><div class="translation-tools"><select aria-label="译文语言" data-translation-language>${[['zh-CN','简体中文'],['zh-TW','繁體中文'],['ja','日本語'],['en','English']].map(([id,name])=>`<option data-i18n-skip value="${id}" ${target===id?'selected':''}>${name}</option>`).join('')}</select><button type="button" class="button secondary small" data-translate>点击翻译</button></div><p class="translation-status" role="status"></p><div class="translation-result" data-i18n-skip hidden></div><small class="translation-note" hidden>机器翻译，仅供理解；点位名称、地址和导航指令保留原文。译文仅此页面有效，刷新或关闭后清除。</small></section>`;}
export function clearTranslations(){generation++;cache.clear();for(const controller of requests)controller.abort();requests.clear();for(const box of document.querySelectorAll('.community-translation')){const result=box.querySelector('.translation-result');result.textContent='';result.hidden=true;box.querySelector('.translation-note').hidden=true;box.querySelector('.translation-status').textContent='';const button=box.querySelector('[data-translate]');button.disabled=false;button.textContent='点击翻译';}}
export function startCommunityTranslation(){if(started)return;started=true;window.addEventListener('pagehide',clearTranslations);window.addEventListener('pageshow',e=>{if(e.persisted)clearTranslations();});document.addEventListener('click',async e=>{
 const button=e.target.closest('[data-translate]');if(!button)return;const box=button.closest('.community-translation'),language=box.querySelector('[data-translation-language]').value,key=JSON.stringify([box.dataset.translationPoint,box.dataset.translationVersion,language]);const result=box.querySelector('.translation-result'),status=box.querySelector('.translation-status'),note=box.querySelector('.translation-note');const show=value=>{result.textContent=value;result.hidden=false;note.hidden=false;status.textContent='译文仅保存在当前页面';};
 widgets.get(box)?.abort();if(cache.has(key)){show(cache.get(key));return;}const controller=new AbortController(),stamp=generation;widgets.set(box,controller);requests.add(controller);button.disabled=true;status.textContent='正在本机翻译…';result.hidden=true;note.hidden=true;
 try{const response=await fetch('/api/translation',{method:'POST',credentials:'same-origin',cache:'no-store',signal:controller.signal,headers:{'Content-Type':'application/json'},body:JSON.stringify({pointId:box.dataset.translationPoint,target:language})});const data=await response.json();if(!response.ok)throw Error(data.error||'翻译暂不可用，请重试');if(typeof data.text!=='string')throw Error('翻译结果无效，请重试');if(generation!==stamp||controller.signal.aborted||widgets.get(box)!==controller)return;cache.set(key,data.text);if(cache.size>60)cache.delete(cache.keys().next().value);if(box.isConnected)show(data.text);}catch(error){if(error.name!=='AbortError'&&generation===stamp&&widgets.get(box)===controller&&box.isConnected)status.textContent=error.message||'翻译失败，请重试';}finally{requests.delete(controller);if(widgets.get(box)===controller){widgets.delete(box);if(box.isConnected)button.disabled=false;}}
 });document.addEventListener('change',e=>{if(!e.target.matches('[data-translation-language]'))return;const box=e.target.closest('.community-translation');widgets.get(box)?.abort();widgets.delete(box);box.querySelector('[data-translate]').disabled=false;box.querySelector('.translation-result').textContent='';box.querySelector('.translation-result').hidden=true;box.querySelector('.translation-note').hidden=true;box.querySelector('.translation-status').textContent='';});}
